"""Coordinate-descent with multi-start and adaptive step refinement."""

import math

def _clip(v, low, high):
    if v < low:
        return low
    if v > high:
        return high
    return v

def search_algorithm(objective, budget, rng, bounds):
    low, high = bounds
    span = high - low

    best_x = rng.uniform(low, high)
    best_y = rng.uniform(low, high)
    best_value = objective(best_x, best_y)
    calls = 1

    num_starts = 4
    starts = []
    for _ in range(num_starts):
        starts.append((rng.uniform(low, high), rng.uniform(low, high)))

    for sx, sy in starts:
        if calls >= budget:
            break
        x = _clip(sx, low, high)
        y = _clip(sy, low, high)
        if calls == 0:
            val = objective(x, y)
            calls += 1
        else:
            val = objective(x, y)
            calls += 1
        if val < best_value:
            best_x, best_y, best_value = x, y, val

        step = span * 0.25
        while step > 1e-3 and calls < budget:
            improved = True
            while improved and calls < budget:
                improved = False
                for sign in (-1, 1):
                    if calls >= budget:
                        break
                    nx = _clip(x + sign * step, low, high)
                    nv = objective(nx, y)
                    calls += 1
                    if nv < val:
                        x, val = nx, nv
                        improved = True
                        if val < best_value:
                            best_x, best_y, best_value = x, y, val
                for sign in (-1, 1):
                    if calls >= budget:
                        break
                    ny = _clip(y + sign * step, low, high)
                    nv = objective(x, ny)
                    calls += 1
                    if nv < val:
                        y, val = ny, nv
                        improved = True
                        if val < best_value:
                            best_x, best_y, best_value = x, y, val
            step *= 0.5

    if calls < budget:
        x, y, val = best_x, best_y, best_value
        step = span * 0.05
        while step > 1e-4 and calls < budget:
            improved = True
            while improved and calls < budget:
                improved = False
                for sign in (-1, 1):
                    if calls >= budget:
                        break
                    nx = _clip(x + sign * step, low, high)
                    nv = objective(nx, y)
                    calls += 1
                    if nv < val:
                        x, val = nx, nv
                        improved = True
                        if val < best_value:
                            best_x, best_y, best_value = x, y, val
                for sign in (-1, 1):
                    if calls >= budget:
                        break
                    ny = _clip(y + sign * step, low, high)
                    nv = objective(x, ny)
                    calls += 1
                    if nv < val:
                        y, val = ny, nv
                        improved = True
                        if val < best_value:
                            best_x, best_y, best_value = x, y, val
            step *= 0.5

    return best_x, best_y
